/**
 *
 * SelectArrow is a component that displays the arrow of a select popup.
 *
 * [Live Demo](https://www.primereact.org/select/)
 *
 * @module SelectArrow
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { SelectRootInstance } from './SelectRoot.types';
/**
 * Defines passthrough(pt) options type in SelectArrow component.
 */
export type SelectArrowPassThroughType<E> = PassThroughType<SelectArrowInstance, E>;
/**
 * Defines passthrough(pt) options of SelectArrow component.
 */
export interface SelectArrowPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: SelectArrowPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in SelectArrow component.
 */
export interface SelectArrowProps extends BaseComponentProps<SelectArrowInstance, unknown, SelectArrowPassThrough> {
}
/**
 * Defines valid state in SelectArrow component.
 */
export interface SelectArrowState {
}
/**
 * Defines the methods and properties exposed by SelectArrow component.
 */
export interface SelectArrowExposes {
    /**
     * The Select component instance.
     */
    select: SelectRootInstance | undefined | null;
}
/**
 * Instance of SelectArrow component.
 */
export type SelectArrowInstance = ComponentInstance<SelectArrowProps, SelectArrowState, SelectArrowExposes>;
